def fill_existing_emails(apps, schema_editor):
    """Generate temporary email addresses for existing users without email."""
    CustomUser = apps.get_model('users', 'CustomUser')
    # Use a counter to ensure uniqueness
    counter = 1
    for user in CustomUser.objects.filter(email__isnull=True):
        # Generate a unique temporary email based on user ID
        temp_email = f'user{user.id}{counter}@temp.kvartirkin.local'
        counter += 1
        user.email = temp_email
        user.save(update_fields=['email'])


